import sys; sys.path.insert(0, '/workspace/site/scripts/guides')
from ghelp import *
GUIDES = []
A = GUIDES.append

A(mk('protect-your-business-from-an-instagram-ban',
 'Protect your business from an Instagram ban: a continuity plan',
 'Protect Your Business From an Instagram Ban: Continuity Plan',
 'A practical plan so losing an Instagram account doesn’t sink your business: backups, access, email lists and habits that keep you within the rules.',
 'instagram', 'Prevention', 'Instagram',
 'treat Instagram as rented space. Back up your content and contacts, keep access secure and shared, own an email list, and stay inside the rules on automation and fake engagement.',
 'Most businesses discover how much they depend on Instagram on the day it disappears. You can’t make an account ban-proof, but you can make a ban survivable and lower the risks you control.',
 [('first', 'What to do first',
   '<p>Answer one question: if this account vanished today, what would I lose? Customers? Orders? Content? Contacts? Write the list. It shows you what to protect first. For most businesses it’s the audience and the link to customers, not the posts themselves.</p>'),
  ('s1', 'Step 1: Back up what you own',
   '<p>Use Instagram’s download-your-information tool to export posts, Stories, messages and followers lists. Do it monthly, and keep the original photos and videos in your own storage too. See our guide to downloading your data for the steps.</p>'),
  ('s2', 'Step 2: Build channels you own',
   '<p>Collect email addresses or phone numbers with permission, through a sign-up link in your bio. Point to your website. If a platform restricts you, an email list is the one audience nobody can switch off.</p>'),
  ('s3', 'Step 3: Secure access properly',
   '<ul><li>Use a unique password and an authentication app, and store backup codes safely.</li><li>Keep a current email and phone number, with a mailbox only your business controls.</li><li>Give team members their own access through Accounts Center and Meta business tools instead of sharing a password.</li><li>Review who has access whenever someone leaves.</li></ul>'),
  ('s4', 'Step 4: Stay within the rules',
   '<p>Meta’s policies discourage fake engagement and automated behaviour. Avoid buying followers, using bots to like or comment, mass-following and unofficial automation tools that ask for your password. These are among the common triggers of restrictions and are easy to avoid.</p>'),
  ('s5', 'Step 5: Check your standing regularly',
   '<p>Open Account Status monthly and read any notices straight away. Fixing a small issue early is easier than appealing a large one later.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t keep a backup “spare” account</strong> to dodge a restriction. Running a second account to get around enforcement is itself a violation.</li><li><strong>Don’t rely on one person’s phone number</strong> for recovery.</li><li><strong>Don’t ignore warnings</strong> because the account still seems to work.</li></ul>')],
 [('Can I make an Instagram account ban-proof?', 'No. You can lower the risk and reduce the damage if it happens.'),
  ('Is a second account allowed?', 'Instagram allows multiple accounts, for example personal and business, but using one to avoid an enforcement action isn’t allowed.'),
  ('What should I back up first?', 'Your customer contacts and your best content, followed by a full data download.')],
 [('Instagram Help Center: Download your information', 'https://help.instagram.com/181231772500920'), ('Instagram Terms and Community Guidelines', 'https://help.instagram.com/477434105621119'), IG_HELP],
 [('/guides/why-instagram-bans-accounts/', 'Why Instagram bans accounts'), ('/guides/instagram-download-your-data-backup/', 'Download your Instagram data'), ('/guides/instagram-check-account-status/', 'Check Instagram Account Status')],
 ['/guides/why-instagram-bans-accounts/', '/guides/instagram-account-disabled/'],
 'I want to protect my business Instagram account from being banned and need a plan', 'Instagram business continuity',
 ('Relying on Instagram?', 'Ask us for a quick audit', 'Tell us how you use the account and we’ll point out the weak spots.'),
 ('Already locked out?', 'We’ll help with the appeal', 'Message us the username and the notice. We use the official appeal route.'),
 pill='Protect your business from a ban'))

A(mk('instagram-account-restored-next-steps',
 'Your Instagram account is back: what to do in the first week',
 'Instagram Account Restored? What to Do Next',
 'You’ve regained an Instagram account after a lock, hack or appeal. Secure it, check what changed and avoid the habits that cause a repeat.',
 'instagram', 'After recovery', 'Instagram',
 'secure the account first: change the password, check logins, confirm contact details and turn on two-factor authentication. Then review what changed and post gently.',
 'Getting an account back is only half the job. The same weakness that let someone in, or the same activity that got you restricted, can cause a repeat if you carry on as before.',
 [('first', 'What to do first',
   '<p>Don’t post, follow or message anyone yet. Take ten minutes to lock things down. If the account was hacked, assume whoever had it may still have the email or a saved login somewhere.</p>'),
  ('s1', 'Step 1: Change the password and sign out other devices',
   '<p>Set a new, unique password in Accounts Center under Password and security, and use the sessions list to log out everywhere else. Do it on a device you trust.</p>'),
  ('s2', 'Step 2: Check email, phone and linked accounts',
   '<p>Open Contact info and make sure the email and phone are yours. Review linked accounts and remove third-party apps you don’t recognise. If the email linked is not yours, change it and secure that mailbox too.</p>'),
  ('s3', 'Step 3: Turn on two-factor authentication',
   '<p>Use an authentication app and save backup codes somewhere safe. See our guide on lost two-factor access for what to do if you’re ever locked out.</p>'),
  ('s4', 'Step 4: Review what changed',
   '<ul><li>Look through recent posts, Stories, bio and links for edits you didn’t make.</li><li>Check sent messages and the accounts you follow.</li><li>Open Account Status for removed content or feature limits.</li><li>Warn followers about any suspicious messages sent from your account.</li></ul>'),
  ('s5', 'Step 5: Ease back in',
   '<p>If the account was restricted for activity, return slowly. Post normally, avoid bulk follows, likes or comments, and don’t reuse anything that was removed.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t publicly announce details of how you got it back</strong> in a way that invites scammers.</li><li><strong>Don’t reconnect suspicious apps</strong> or tools.</li><li><strong>Don’t assume the problem is over</strong> without checking Account Status.</li></ul>')],
 [('Can the account be banned again right after recovery?', 'It can if the underlying cause continues. Review what happened and adjust.'),
  ('Should I tell followers?', 'If the account sent messages or posts you didn’t make, yes, so they don’t click bad links.'),
  ('Does my reach return straight away?', 'Meta doesn’t publish a timeline for any recovery of reach, so be patient and consistent.')],
 [('Instagram: hacked or inaccessible accounts', 'https://www.instagram.com/hacked/'), IG_HELP, ('Instagram Help: Account Status', 'https://help.instagram.com/338481628002750')],
 [('/guides/hacked-instagram-account-recovery/', 'Hacked Instagram account recovery'), ('/guides/instagram-check-account-status/', 'Check Instagram Account Status'), ('/guides/protect-your-business-from-an-instagram-ban/', 'Protect your business from a ban')],
 ['/guides/hacked-instagram-account-recovery/', '/guides/instagram-account-suspended-appeal/'],
 'My Instagram account is restored and I want to make sure it stays safe', 'Instagram restored account',
 ('Account back?', 'Ask for a quick security check', 'Tell us what happened and we’ll give you a checklist for the first week.'),
 ('Something still wrong?', 'We’ll help you work it out', 'Message us what you’re seeing. We use official routes only.'),
 pill='Account restored next steps'))

A(mk('instagram-harassment-dms-what-to-do',
 'Harassing DMs on Instagram: protect yourself and report properly',
 'Harassing Instagram DMs: Protect Yourself & Report',
 'Block, restrict, filter and report abusive messages on Instagram. What to save, which tools to use first and how to handle new accounts.',
 'instagram', 'Safety', 'Instagram',
 'save evidence, block the account (including new ones they may create), turn on Hidden Words and report the chat. If you feel unsafe, contact local authorities.',
 'Getting repeated abusive messages is exhausting. Instagram has tools that put distance between you and the sender quickly. Use them in order and keep a record, so you have options if the behaviour continues.',
 [('first', 'What to do first',
   '<p>If you’re in immediate danger, contact your local emergency number. Otherwise, don’t reply. Screenshot the messages with the sender’s username and the dates visible, and copy the profile link. Evidence is easy to lose if the sender deletes messages or their account.</p>'),
  ('s1', 'Step 1: Block, and block future accounts',
   '<p>From the sender’s profile, choose Block. Instagram’s block tool also lets you block new accounts the person may create, which helps when someone keeps coming back with fresh usernames. It won’t catch every account, but it reduces repeat contact.</p>'),
  ('s2', 'Step 2: Use Restrict if blocking would escalate',
   '<p>Restrict moves the person’s messages to requests and hides their comments from others without telling them. It’s useful when the person is someone you know and a block would cause conflict. You can read their messages without them seeing that you did, and you can unrestrict later.</p>'),
  ('s3', 'Step 3: Filter with Hidden Words',
   '<p>In your settings, turn on Hidden Words to filter offensive message requests and comments, and add words or emojis of your own. It works in the background and spares you from reading abuse.</p>'),
  ('s4', 'Step 4: Report the chat',
   '<p>Open the conversation, tap the name at the top, choose Report and pick the reason that fits. You can also press and hold an individual message to report it. Report each account separately. Meta doesn’t publish a timeline, and sending more reports doesn’t speed it up.</p>'),
  ('s5', 'Step 5: Limit who can contact you',
   '<p>Use Limits and the message controls to restrict who can message you, especially if you’ve got a public account that’s targeted by a wave of messages.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t reply or argue.</strong> It tends to prolong contact.</li><li><strong>Don’t organise others to mass-report.</strong> Reports are assessed on content, not counts.</li><li><strong>Don’t share personal details</strong> about the person publicly.</li></ul>'),
  ('help', 'Getting support',
   '<p>Talk to someone you trust, and keep screenshots in a safe place. If threats are involved, police can act in ways Instagram can’t.</p>')],
 [('Will the person know I reported them?', 'No. Reports are confidential.'),
  ('Can I stop message requests from strangers?', 'You can limit who can message you in the privacy settings, and filter with Hidden Words.'),
  ('What if they’ve made new accounts?', 'Block with the option to include new accounts, report each one and keep a list.')],
 [('Instagram Help: Report a chat', 'https://help.instagram.com/568100683269916'), ('Instagram Help: Hidden Words', 'https://help.instagram.com/700284123459336'), ('Instagram Help: Restrict', 'https://help.instagram.com/2638385956221960')],
 [('/someone-keeps-making-new-accounts-to-harass-me/', 'Someone keeps making new accounts to harass me'), ('/harassment-account-removal/', 'Harassment account removal'), ('/instagram-not-removing-reported-account/', 'Instagram not removing a reported account')],
 ['/harassment-account-removal/', '/someone-keeps-making-new-accounts-to-harass-me/'],
 'Someone is sending me harassing messages on Instagram and I want to report them properly', 'Instagram harassment report',
 ('Being harassed?', 'Tell us what’s happening', 'Share the username and what’s been sent. We’ll help you report it the official way.'),
 ('Report not working?', 'We’ll help build a clear report', 'Message us the details and what you’ve reported. We’ll help you put together an accurate report.'),
 svc='ban', pill='Harassing DMs on Instagram'))

A(mk('instagram-scam-dm-what-to-do',
 'Got a scam DM on Instagram? What to do before and after you click',
 'Instagram Scam DM: What to Do Before & After You Click',
 'Spot the common scam messages on Instagram, what to do if you clicked or paid, and how to report the account the right way.',
 'instagram', 'Scams', 'Instagram',
 'don’t click, reply or pay. Report the message, block the account and save evidence. If you already paid or shared a password, act within the hour on your bank and your login.',
 'Scam DMs have a few recurring shapes. Recognising them takes seconds, and the right response after a mistake limits the damage a lot.',
 [('first', 'What to do first',
   '<p>Stop. Don’t reply, don’t click and don’t send money, codes or ID. Take a screenshot of the message and the profile. If it came from a friend’s account, that account may be hacked, so contact the friend another way.</p>'),
  ('s1', 'Step 1: Recognise the common shapes',
   '<ul><li><strong>“Your account will be banned”</strong> messages with a link to appeal or verify.</li><li><strong>Giveaway and prize</strong> messages that need a fee or details first.</li><li><strong>Fake brand or collaboration</strong> offers that ask you to click a link or pay for “shipping”.</li><li><strong>Investment or crypto tips</strong> promising returns.</li><li><strong>Fake sellers</strong> who ask you to pay by transfer outside the app.</li><li><strong>Hacked friends</strong> asking for codes or urgent money.</li></ul>'),
  ('s2', 'Step 2: Report and block',
   '<p>Open the chat, tap the name, choose Report and pick the scam or fraud option. Then block the account. If you’re reporting a fake business account, also use the profile’s three-dot menu to report impersonation.</p>'),
  ('s3', 'Step 3: If you clicked or entered details',
   '<p>Change your Instagram password right away, log out other sessions and check Recent emails in Accounts Center. If you entered a code, treat the account as compromised and follow our hacked-account guide. If you used the same password elsewhere, change those too.</p>'),
  ('s4', 'Step 4: If you paid',
   '<p>Contact your bank or payment provider immediately and ask about stopping or disputing the payment. Report the fraud to your local consumer protection authority or police. Instagram can’t refund money sent to a scammer.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t pay “recovery fees”</strong> to someone who says they can get lost money back. That’s a second scam.</li><li><strong>Don’t send ID or codes</strong> to anyone in a DM.</li><li><strong>Don’t post the scammer’s personal details</strong> publicly.</li></ul>')],
 [('How do I know a message is really from Instagram?', 'Official emails come from Instagram’s own domains and appear in your Recent emails list in the app. Instagram doesn’t ask for passwords by DM.'),
  ('Can Instagram get my money back?', 'No. Contact your bank and local authorities.'),
  ('What if a friend sent it?', 'Their account may be compromised. Tell them through another channel.')],
 [('Instagram Help: Report a chat', 'https://help.instagram.com/568100683269916'), ('Meta Scam Protection Center', 'https://www.meta.com/safety/scam-protection-center/'), IG_HACKED],
 [('/instagram-seller-scammed-me/', 'Instagram seller scammed me'), ('/scammer-account-removal/', 'Scammer account removal'), ('/guides/instagram-fake-ban-or-copyright-emails/', 'Fake ban emails')],
 ['/instagram-seller-scammed-me/', '/scammer-account-removal/'],
 'I got a scam message on Instagram and want to report the account properly', 'Instagram scam report',
 ('Think it’s a scam?', 'Send us a screenshot', 'We’ll tell you what we’d do and how to report it.'),
 ('Need to report one?', 'We’ll help you do it right', 'Message us the username and what happened. We’ll help you report it properly.'),
 svc='ban', pill='Instagram scam DM'))

A(mk('sextortion-what-to-do-on-instagram',
 'Sextortion on Instagram: what to do right now',
 'Sextortion on Instagram: What to Do Right Now',
 'If someone is threatening to share your private images, don’t pay. Stop contact, save evidence, report and use StopNCII or NCMEC’s Take It Down.',
 'instagram', 'Safety', 'Instagram',
 'don’t pay, stop replying, block and report the account, keep evidence, and use StopNCII.org (18+) or NCMEC’s Take It Down (under 18) to help stop images spreading.',
 'Sextortion is a crime, and it’s not your fault. Someone threatens to share intimate images unless you pay or send more. Acting calmly and quickly protects you, and there are free tools designed for exactly this.',
 [('first', 'What to do first',
   '<p>Stop replying. Don’t pay and don’t send more images. Paying rarely ends it, and threats often continue. If you’re under 18 or feel in danger, tell a trusted adult or contact local police straight away.</p>'),
  ('s1', 'Step 1: Keep evidence',
   '<p>Screenshot the messages, the profile and any payment demands before you block. Save usernames, links and dates. Don’t delete the chat yet. This is useful for the police and for Instagram.</p>'),
  ('s2', 'Step 2: Block and report',
   '<p>Report the chat from the conversation menu, choosing the option that fits what they’re doing, then block the account. Instagram’s safety pages explain how to report intimate image threats.</p>'),
  ('s3', 'Step 3: Use image-removal tools',
   '<p>StopNCII.org lets adults create a digital fingerprint of an image on their own device so participating platforms can detect and block it. The image isn’t uploaded. For images taken when you were under 18, NCMEC’s Take It Down service works in a similar way. Both are free and run by recognised organisations.</p>'),
  ('s4', 'Step 4: Contact the authorities and get support',
   '<p>Report to your local police or your country’s online-crime reporting service. Talk with someone you trust, or a support organisation in your country. Shame is what blackmailers rely on, and you’re not alone.</p>'),
  ('s5', 'Step 5: Tighten your account',
   '<p>Set the account to private, review followers, turn on Hidden Words and limit who can message you. Change your password and enable two-factor authentication.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t pay.</strong> It often leads to more demands.</li><li><strong>Don’t delete everything in panic.</strong> Keep evidence first.</li><li><strong>Don’t blame yourself.</strong> The person making threats is responsible.</li></ul>')],
 [('Will paying make it stop?', 'Usually not. Many victims report that demands continue.'),
  ('Does StopNCII upload my image?', 'No. It creates a hash on your device, and the image isn’t sent.'),
  ('Can Instagram remove the account?', 'You can report it. Meta doesn’t publish a timeline, so also contact the police.')],
 [('Meta Safety: Non-consensual intimate images', 'https://www.meta.com/safety/topics/bullying-harassment/ncii/'), ('StopNCII.org', 'https://stopncii.org/'), ('NCMEC Take It Down', 'https://takeitdown.ncmec.org/')],
 [('/guides/instagram-harassment-dms-what-to-do/', 'Harassing DMs on Instagram'), ('/guides/instagram-scam-dm-what-to-do/', 'Scam DM on Instagram'), ('/harassment-account-removal/', 'Harassment account removal')],
 ['/harassment-account-removal/'],
 'Someone is threatening me with private images on Instagram and I need help reporting it', 'Sextortion on Instagram',
 ('Being blackmailed?', 'Message us, no judgement', 'Share the username and we’ll help you report the account the official way.'),
 ('Need help reporting?', 'We’ll help you do it properly', 'Message us. We’ll help you prepare an accurate report. Never send us images.'),
 svc='ban', pill='Sextortion on Instagram'))

A(mk('snapchat-account-hacked',
 'Snapchat account hacked: how to secure it or recover it',
 'Hacked Snapchat Account: Secure & Recover It',
 'Steps to take if someone else is using your Snapchat: reset your password, check email and phone, end sessions and contact Snapchat support.',
 'snapchat', 'Hacked', 'Snapchat',
 'reset your password at accounts.snapchat.com, then check your email and phone, log out other devices and turn on two-factor authentication. If you can’t log in, use Snapchat Support’s compromised-account steps.',
 'A Snapchat takeover often starts with a reused password or a phishing link. The aim is to secure the login details, then the email and phone attached to the account, then your friends.',
 [('first', 'What to do first',
   '<p>If you can still log in, change your password straight away to something unique. If you can’t, go to accounts.snapchat.com and use the forgot-password route. Don’t sign in through links from messages or emails.</p>'),
  ('s1', 'Step 1: Reset the password',
   '<p>Use the official Accounts Portal. Choose a password you don’t use anywhere else. Snapchat’s help page says it can only reset a password through an email or number linked to the account, so if you can reach neither, see our guide on lost codes, email and phone.</p>'),
  ('s2', 'Step 2: Check email, phone and devices',
   '<p>In Settings, verify the email and mobile number are yours, and look at the list of logged-in devices. Remove anything you don’t recognise. If someone changed the email, use Snapchat Support’s compromised-account help.</p>'),
  ('s3', 'Step 3: Turn on two-factor authentication',
   '<p>Use an authentication app if offered, or SMS, and save the recovery code. If you lose both, Snapchat’s help pages say lost recovery codes can’t be replaced, so store them well.</p>'),
  ('s4', 'Step 4: Warn friends and check connected apps',
   '<p>Tell friends not to open links sent from your account. Remove third-party apps connected to it. Never share your My Eyes Only passcode either; Snapchat says its team never asks for it.</p>'),
  ('s5', 'Step 5: Contact Snapchat Support',
   '<p>If the account is out of reach, use Snapchat Support (it starts with the Support Bot) for compromised accounts and explain what happened. Include an email address you can access, and expect questions to verify it’s you, such as your username and when you lost access. This is Snapchat’s own process, and Snapchat doesn’t publish a timeline.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t use “Snapchat hacker” services</strong> or pay for recovery. They’re scams.</li><li><strong>Don’t share your password or codes</strong> with anyone, including “support” in DMs.</li><li><strong>Don’t make a new account</strong> and abandon the old one if you want to recover it.</li></ul>')],
 [('Does Snapchat have a phone number for support?', 'Use Snapchat Support’s forms and in-app help. Be careful with numbers found elsewhere.'),
  ('Can friends see what the hacker sent?', 'They may have received messages. Warn them as soon as you can.'),
  ('How long does Snapchat take to respond?', 'It doesn’t publish a timeline. Submit once and check your email.')],
 [('Snapchat Support: My account is compromised', 'https://help.snapchat.com/hc/en-us/articles/7012305621908'), ('Snapchat Support: I can’t access my account', 'https://help.snapchat.com/hc/en-us/articles/23102718270996'), SNAP_ACC],
 [('/guides/snapchat-account-locked/', 'Snapchat account locked'), ('/guides/snapchat-two-factor-or-email-lost/', 'Snapchat two-factor or email lost'), ('/snapchat-unban-service/', 'Snapchat unban service')],
 ['/guides/snapchat-account-locked/'],
 'My Snapchat account was hacked and I need help securing or recovering it', 'Snapchat account hacked',
 ('Snapchat taken over?', 'Tell us what happened', 'Share your username and what changed and we’ll point you to the right Snapchat steps.'),
 ('Locked out?', 'We’ll help with the support request', 'Message us. We use Snapchat’s official routes and never ask for your password.'),
 pill='Hacked Snapchat account'))

A(mk('snapchat-two-factor-or-email-lost',
 'Snapchat login code, email or phone lost: what’s possible and what isn’t',
 'Lost Snapchat Login Code, Email or Number? What’s Possible',
 'Can’t receive your Snapchat verification code or lost the email or phone on the account? Snapchat’s own rules on what it can and can’t reset.',
 'snapchat', 'Login help', 'Snapchat',
 'if you can still reach either the email or the phone on the account, you can reset the password through it. If you can reach neither, Snapchat says it can’t reset the password. A recovery code is the way past a lost two-factor device.',
 'Snapchat is stricter than most platforms here, and it’s better to know the limits than to lose weeks on a dead end. What you can do depends on exactly which piece you’ve lost.',
 [('first', 'What to do first',
   '<p>Work out which of these you still have: the <strong>email</strong> on the account, the <strong>phone number</strong> on the account, a saved <strong>recovery code</strong>, or an <strong>authentication app</strong> on another device. Each opens a different door, and one of them may be enough.</p>'),
  ('s1', 'Step 1: If you have the email or the phone',
   '<p>Snapchat’s help page says that if you have access to either one, you can reset your password using it. Go to accounts.snapchat.com, choose the forgot-password option and use whichever you can reach. You only need one of them.</p>'),
  ('s2', 'Step 2: If the problem is the two-factor code',
   '<p>Enter your <strong>recovery code</strong> where the verification code goes. Snapchat’s help page says this logs you in and turns two-factor authentication off, so set it up again afterwards. If you never created a recovery code or lost it, Snapchat’s help pages say it can’t help with that. If the code simply isn’t arriving, check signal, the number on file and wait a few minutes before asking again.</p>'),
  ('s3', 'Step 3: If you have neither email nor phone',
   '<p>This is the hard one. Snapchat’s help page says that for security reasons it can’t reset a password if the account has no associated email or number, if you don’t know them, or if you can’t access them. Even if you know your username, it can’t reset the password in that situation. Be wary of anyone who says otherwise, because they can’t change Snapchat’s rule either.</p>'),
  ('s4', 'Step 4: Don’t forget the simple causes',
   '<ul><li>Too many login attempts can temporarily block you; Snapchat suggests waiting 48 hours if you’re sure the details are right.</li><li>If you’re not sure of your username, try logging in with the email or number instead, check whether your device saved the login, or ask a friend to read it from your Friendship Profile.</li><li>A device that has saved logins, such as an old phone or a browser, may still hold a session.</li></ul>'),
  ('s5', 'Step 5: Fix it once you’re in',
   '<p>Add a current email and phone, verify both, store a new recovery code and consider an authentication app on a device you keep. That way no single loss locks you out again.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t buy codes or “workaround” tools.</strong> They don’t exist and the sellers want money or your password.</li><li><strong>Don’t request codes over and over</strong> in a short time.</li><li><strong>Don’t share your password or My Eyes Only passcode</strong> with anyone. Snapchat says its team never asks for them.</li></ul>')],
 [('Can Snapchat send a code to a new number?', 'Not on request alone. Snapchat’s help pages describe resets using the email or number already on the account.'),
  ('Does a recovery code turn off two-factor?', 'Snapchat’s help page says logging in with it turns two-factor authentication off.'),
  ('Is there any route if I lost both email and phone?', 'Snapchat’s help page says it can’t reset the password in that situation. Check every old device for a saved session before you give up.')],
 [('Snapchat Support: I can’t access my account', 'https://help.snapchat.com/hc/en-us/articles/23102718270996'), ('Snapchat Support: I can’t receive my code', 'https://help.snapchat.com/hc/en-us/articles/44906175841556'), ('Snapchat Support: How do I use a Recovery Code?', 'https://help.snapchat.com/hc/en-us/articles/7012350903188')],
 [('/guides/snapchat-account-hacked/', 'Hacked Snapchat account'), ('/guides/snapchat-account-locked/', 'Snapchat account locked'), ('/how-long-does-a-snapchat-lock-last/', 'How long does a Snapchat lock last')],
 ['/guides/snapchat-account-locked/'],
 'I lost access to the phone or email on my Snapchat account and want to know my options', 'Snapchat login help',
 ('Can’t get a code?', 'Tell us what you have', 'Share what you can still reach and we’ll tell you honestly what Snapchat allows.'),
 ('Not sure which route?', 'We’ll go through it with you', 'Message us your username and where you’re stuck. No passwords.'),
 pill='Snapchat code or email lost'))

A(mk('snapchat-device-banned-appeal',
 'Snapchat device ban (SS06): what it means and whether you can appeal',
 'Snapchat Device Ban SS06: Meaning & Appeal',
 'What a Snapchat device ban means, how it differs from an account ban and when the login screen offers an appeal.',
 'snapchat', 'Device ban', 'Snapchat',
 'an SS06 message means the device is restricted from Snapchat. If the login screen shows Appeal Decision, use it once. A newly purchased device usually won’t be unbanned.',
 'A device ban is different from an account ban. It’s linked to the phone, so a new account on the same phone can hit the same wall. Snapchat’s help page explains when an appeal is possible.',
 [('first', 'What to do first',
   '<p>Read the exact message on the screen. Write down the error code and whether it mentions an account, a device or a policy. If the login screen offers <em>Appeal Decision</em>, that’s your route. If it doesn’t, an appeal isn’t available from there.</p>'),
  ('s1', 'Step 1: Confirm it’s a device ban',
   '<p>Snapchat’s help page describes error SS06 as a restriction on the device. It means Snapchat has limited that phone’s access, not necessarily that your own username broke the rules.</p>'),
  ('s2', 'Step 2: Use Appeal Decision if offered',
   '<p>On the login screen, choose <em>Appeal Decision</em> and follow the prompts. Give accurate information and submit once. Snapchat doesn’t publish a timeline for decisions.</p>'),
  ('s3', 'Step 3: If you bought the device used',
   '<p>Snapchat’s help page notes that devices bought recently are generally not unbanned. If you suspect the phone came with a ban, check with the seller, and report any problem to them. Also try the same account on a different device you own.</p>'),
  ('s4', 'Step 4: Check your own account separately',
   '<p>Try your username on another phone or the web to see whether the account itself is locked or limited. That tells you which problem you have.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t try to hide or change device identifiers.</strong> That’s a way of dodging the ban and can lead to further action.</li><li><strong>Don’t buy a “ban remover.”</strong> It’s a scam.</li><li><strong>Don’t submit multiple appeals</strong> in a row.</li></ul>')],
 [('Is SS06 permanent?', 'Snapchat’s help page says appeal is only available if the login screen offers it. Otherwise it’s a final decision.'),
  ('Can I use my account on another phone?', 'If the account isn’t banned, usually yes. Check the message you see.'),
  ('Does a factory reset remove the ban?', 'No. Snapchat’s help page doesn’t suggest it will.')],
 [('Snapchat Support: Device ban (SS06)', 'https://help.snapchat.com/hc/en-us/articles/48008135555860'), SNAP_HELP, SNAP_ACC],
 [('/guides/snapchat-account-locked/', 'Snapchat account locked'), ('/can-a-permanently-banned-snapchat-account-be-recovered/', 'Can a banned Snapchat account be recovered'), ('/snapchat-unban-service/', 'Snapchat unban service')],
 ['/can-a-permanently-banned-snapchat-account-be-recovered/', '/snapchat-unban-service/'],
 'My phone shows a Snapchat device ban SS06 and I want to know if I can appeal', 'Snapchat device ban',
 ('Seeing SS06?', 'Send us the screen', 'Share a screenshot of the login message and we’ll tell you what the options are.'),
 ('Want the appeal done right?', 'We’ll help you prepare it', 'Message us the details. We use Snapchat’s official appeal only.'),
 pill='Snapchat device ban'))

A(mk('snapchat-change-username-and-delete-account',
 'Snapchat username, deactivation and deletion: what you can and can’t change',
 'Snapchat Username, Deactivate & Delete: What You Can Change',
 'Snapchat usernames can’t be freely changed, and deleting an account is a 30-day process. Learn the rules and the steps before you decide.',
 'snapchat', 'Account', 'Snapchat',
 'Snapchat lets you change a username once a year and deletion takes about 30 days. Log in within that window to reactivate.',
 'These are two of the most misunderstood Snapchat settings. One can’t be done freely, and the other isn’t instant. Knowing the rules beforehand avoids regret.',
 [('first', 'What to do first',
   '<p>Decide what you’re trying to achieve. If you want a different public name, change your display name, which is free to edit. If you want a new username, check the yearly limit. If you want a break from Snapchat, deactivation is the same as deletion on Snapchat, so save your memories first.</p>'),
  ('s1', 'Step 1: Username versus display name',
   '<p>The display name is what friends see and can be changed whenever you like. The username is the unique handle, and Snapchat’s help page says it can be changed once a year. Check the current limit in help before you commit.</p>'),
  ('s2', 'Step 2: Change the username',
   '<p>Open your profile, go to Settings, choose Username and follow the prompts. If the name you want is taken, you’ll need another. Friends and snaps stay with the account when you change it.</p>'),
  ('s3', 'Step 3: How deactivation and deletion work',
   '<p>Snapchat’s help page says when you delete your account it’s deactivated first, and is permanently deleted after 30 days. Logging in during that period with your username and password can reactivate it. Use the accounts portal to start the process.</p>'),
  ('s4', 'Step 4: Save what you care about',
   '<p>Before deleting, download your data from the Accounts Portal, including memories and chats, and tell friends how else to contact you. After permanent deletion, there’s no way to get the account back.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t log in during the 30 days</strong> if you want deletion to proceed.</li><li><strong>Don’t delete to escape a lock.</strong> It doesn’t remove it and ends your chance of recovery.</li><li><strong>Don’t pay for username swaps</strong> or “premium” usernames. That’s a scam, and selling or buying is not allowed.</li></ul>')],
 [('Can I change my username more than once a year?', 'Snapchat’s help page says once a year. Check it for current details.'),
  ('Can I reactivate a deleted account?', 'Within 30 days by logging in. After that, no.'),
  ('Will my memories stay?', 'Not after deletion. Download them first.')],
 [('Snapchat Support: Change your username', 'https://help.snapchat.com/hc/en-us/articles/7012349845140'), ('Snapchat Support: Delete or deactivate account', 'https://help.snapchat.com/hc/en-us/articles/7012328360596'), ('Snapchat Support: Reactivate account', 'https://help.snapchat.com/hc/en-us/articles/7012367354132')],
 [('/guides/snapchat-account-locked/', 'Snapchat account locked'), ('/guides/snapchat-account-hacked/', 'Hacked Snapchat account'), ('/guides/snapchat-two-factor-or-email-lost/', 'Snapchat login help')],
 ['/guides/snapchat-account-locked/'],
 'I want to change my Snapchat username or delete my account and want to check the rules', 'Snapchat username or delete',
 ('Not sure what to do?', 'Ask us first', 'Tell us what you want to change and we’ll tell you what Snapchat allows.'),
 ('Deleted by mistake?', 'We’ll check the options', 'Message us the username and when you started deletion. We’ll tell you what’s possible.'),
 pill='Snapchat username and deletion'))

A(mk('threads-deactivate-or-delete',
 'Threads: delete or deactivate without losing Instagram',
 'Delete or Deactivate Threads Without Losing Instagram',
 'You can delete a Threads profile separately from Instagram. What happens, the 30-day window and what to do first.',
 'instagram', 'Threads', 'Instagram',
 'in Threads go to your profile, Menu, Account settings, Personal details, Deactivation or deletion. You can delete or deactivate Threads separately from Instagram.',
 'Threads is tied to an Instagram account, but you don’t have to lose one to get rid of the other. The options are separate, and so are the consequences.',
 [('first', 'What to do first',
   '<p>Decide what you want: a break, or removal. Download your Threads information if you may want it later. Then check whether Threads is where you answer customers or run a brand, because deactivating makes it disappear for them too.</p>'),
  ('s1', 'Step 1: Choose deactivate or delete',
   '<p>Deactivating hides your Threads profile, posts and likes, and you can bring it back by logging in. Deleting removes your Threads profile and content permanently once the window passes. Meta’s help pages describe a 30-day period before deletion takes effect.</p>'),
  ('s2', 'Step 2: Do it in the Threads app',
   '<p>Open Threads, go to your profile, tap the menu, then <em>Account settings</em>, <em>Personal details</em> and <em>Deactivation or deletion</em>. Choose the Threads profile and follow the prompts. Pick delete only for the Threads profile unless you intend to remove Instagram too.</p>'),
  ('s3', 'Step 3: Know what stays',
   '<p>Your Instagram account and its posts aren’t deleted when you remove Threads alone. Your Threads username may be linked to your Instagram, so read the screens carefully.</p>'),
  ('s4', 'Step 4: Cancel if you change your mind',
   '<p>Logging back in during the waiting period can cancel deletion. Don’t log in if you want it to proceed.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t delete your Instagram</strong> when you only meant to leave Threads.</li><li><strong>Don’t assume a suspended Threads means Instagram is gone.</strong> They can be affected separately.</li><li><strong>Don’t use unofficial “cleaner” apps</strong> that ask for your login.</li></ul>')],
 [('Does deleting Threads delete Instagram?', 'No. They can be removed separately.'),
  ('Can I get my Threads username back?', 'Not after deletion if someone else takes it. Think before you delete.'),
  ('What if Threads is suspended but Instagram works?', 'See our guide on Threads suspensions. The two can be actioned independently.')],
 [('Instagram Help: Delete your Threads profile', 'https://help.instagram.com/313703828012423'), ('Instagram Help: Deactivate Threads', 'https://www.facebook.com/help/instagram/558007373138554'), IG_HELP],
 [('/threads-suspended-but-instagram-works/', 'Threads suspended but Instagram works'), ('/threads-account-suspended/', 'Threads account suspended'), ('/guides/instagram-deactivate-or-delete-account/', 'Deactivate or delete Instagram')],
 ['/threads-suspended-but-instagram-works/', '/threads-account-suspended/'],
 'I want to remove my Threads profile without affecting Instagram and want to check the steps', 'Threads delete or deactivate',
 ('Unsure what happens?', 'Ask before you delete', 'Tell us what you want to keep and we’ll tell you what to watch for.'),
 ('Threads suspended?', 'We’ll look at the appeal route', 'Message us the username and the notice. We use official routes only.'),
 pill='Delete or deactivate Threads'))

A(mk('account-recovery-scams-fake-hackers-warning',
 'Account recovery scams: how fake “hackers” and “Meta agents” work',
 'Account Recovery Scams: Fake Hackers & Fake Agents',
 'People who lose an account are targeted by fake recovery services. Learn the tactics, how to check any helper and what a safe recovery looks like.',
 'instagram', 'Scams', None,
 'any helper who asks for your password, a code, an upfront payment in gift cards or crypto, or claims inside contacts at Meta is a scam. Recovery only happens through official routes.',
 'When an account is locked or hacked, the person who lost it is under pressure and looking for help. Scammers know that, and they find victims in comments, DMs and search ads within hours.',
 [('first', 'What to do first',
   '<p>Pause before you reply to any offer of help you didn’t ask for. Then check the official route for your platform, such as the Instagram, Facebook or Snapchat help pages. If you’ve already contacted someone, stop sending information and read the warning signs below.</p>'),
  ('s1', 'Step 1: Know the warning signs',
   '<ul><li>They contacted you first, often in comments or by DM.</li><li>They ask for your password, a login code, or access to your email.</li><li>They ask for payment in gift cards, crypto or by transfer before doing anything.</li><li>They claim to have an inside contact or a special tool.</li><li>They say the account will be deleted unless you act now.</li><li>They push you to move to Telegram or WhatsApp.</li></ul>'),
  ('s2', 'Step 2: Understand how real recovery works',
   '<p>Genuine recovery uses the platform’s own forms: login help, identity checks with ID or a video selfie, and appeals inside the app. No outside party can force a platform’s decision. Anyone promising that they can is offering something that doesn’t exist.</p>'),
  ('s3', 'Step 3: Check any helper, including us',
   '<p>Ask what exactly they’ll do, and whether they need your password. A legitimate adviser explains the official route, doesn’t ask for your login, doesn’t claim a connection inside the platform and doesn’t promise outcomes. Be wary of anything that sounds too good.</p>'),
  ('s4', 'Step 4: If you’ve been scammed',
   '<p>Change the passwords of the account and its email, log out other sessions, and contact your bank about payments. Report the scammer to the platform and local authorities. Save screenshots of the conversation.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t give anyone your login or codes.</strong></li><li><strong>Don’t pay to “unlock” a recovery.</strong></li><li><strong>Don’t be embarrassed.</strong> These scams are designed to catch careful people at a stressful moment.</li></ul>')],
 [('Can anyone at Meta help me for a fee?', 'No. Anyone who says so is not telling the truth. Use the official forms.'),
  ('Are all recovery services scams?', 'Not all, but the ones that ask for your password, promise results, or claim inside access are.'),
  ('What should a safe adviser do?', 'Explain the official route, ask for no passwords and promise no outcomes.')],
 [('Meta Scam Protection Center', 'https://www.meta.com/safety/scam-protection-center/'), IG_HACKED, FB_HACKED],
 [('/guides/hacked-instagram-account-recovery/', 'Hacked Instagram account recovery'), ('/guides/instagram-scam-dm-what-to-do/', 'Scam DM on Instagram'), ('/guides/instagram-fake-ban-or-copyright-emails/', 'Fake ban emails')],
 ['/guides/hacked-instagram-account-recovery/'],
 'I want to check whether someone offering to recover my account is legitimate', 'Recovery scam check',
 ('Not sure who to trust?', 'Send us what they said', 'Share the message and we’ll tell you what looks off.'),
 ('Already paid someone?', 'We’ll help you with next steps', 'Message us what happened. We’ll help with securing the account and reporting.'),
 svc='ban', pill='Account recovery scams'))
